+	shapeTagLaxLoop typeTag = 7
+
+	maxEncodedShapes          = 10000000
+	maxEncodedShapeIndexCells = 10000000
+	maxEncodedClippedShapes   = 10000000
+	maxEncodedClippedEdges    = 50000000
